def semver_sort(versions):
    def parse(v):
        main_build = v.split('+', 1)
        main_part = main_build[0]
        if '-' in main_part:
            core, prerelease = main_part.split('-', 1)
        else:
            core, prerelease = main_part, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if prerelease is None:
            has_pre = 1  # no prerelease sorts after
            ids = []
        else:
            has_pre = 0  # has prerelease sorts before
            ids = []
            for ident in prerelease.split('.'):
                if ident.isdigit():
                    ids.append((0, int(ident), ''))
                else:
                    ids.append((1, 0, ident))

        return (major, minor, patch, has_pre, ids)

    return sorted(versions, key=parse)

